  "b14-deniz-kafesinde-balik-boyunu-olcen": YzGorsel(kimlik: "b14-deniz-kafesinde-balik-boyunu-olcen", adres: "/yz/gorsel/b14-deniz-kafesinde-balik-boyunu-olcen.webp",
