  "t-goruntu-tanzanya-daki-saha-denemesinde": YzGorsel(kimlik: "t-goruntu-tanzanya-daki-saha-denemesinde", adres: "/yz/gorsel/b26-tanzanya-tarla-deneyinden-manyok.webp",
